<?php require_once __DIR__.'/includes/functions.php';require_role(['admin','staff']);if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$act=$_POST['action']??'';if($act==='delete'){$s=$db->prepare('DELETE FROM categories WHERE id=?');$s->bind_param('i',$id);$s->execute();log_action('category_deleted','categories',$id);flash('Category deleted; associated books remain uncategorized.');}else{$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');if($name==='')flash('Category name is required.','error');else{try{if($id){$s=$db->prepare('UPDATE categories SET name=?,description=? WHERE id=?');$s->bind_param('ssi',$name,$desc,$id);}else{$s=$db->prepare('INSERT INTO categories(name,description) VALUES(?,?)');$s->bind_param('ss',$name,$desc);}$s->execute();log_action($id?'category_updated':'category_created','categories',$id?:$db->insert_id,$name);flash('Category saved.');}catch(Throwable $e){flash('Could not save category; the name may already exist.','error');}}}header('Location: '.url('categories.php'));exit;}$rows=$db->query('SELECT c.*,COUNT(b.id) book_count FROM categories c LEFT JOIN books b ON b.category_id=c.id GROUP BY c.id ORDER BY c.name');$title='Categories';require 'includes/header.php';?><h1>Book categories</h1><div class="panel"><h2>Add category</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Name</label><input name="name" required maxlength="100"><label>Description</label><input name="description" maxlength="255"><button>Add category</button></form></div><div class="panel table-wrap"><table><tr><th>Category</th><th>Description</th><th>Books</th><th>Actions</th></tr><?php while($c=$rows->fetch_assoc()):?><tr><td><?=e($c['name'])?></td><td><?=e($c['description'])?></td><td><?=$c['book_count']?></td><td><details><summary>Edit</summary><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$c['id']?>"><label>Name</label><input name="name" value="<?=e($c['name'])?>" required><label>Description</label><input name="description" value="<?=e($c['description'])?>"><button>Update</button></form><form method="post" data-confirm="Delete category? Books will become uncategorized."><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn danger" name="action" value="delete">Delete</button></form></details></td></tr><?php endwhile;?></table></div><?php require 'includes/footer.php';?>
